def create_topics_and_map_questions(apps, schema_editor):
    """Create Topic objects from existing question.topic CharField values"""
    Question = apps.get_model('quiz', 'Question')
    Topic = apps.get_model('quiz', 'Topic')
    
    # Get all unique topic values
    unique_topics = Question.objects.filter(
        topic__isnull=False
    ).values_list('topic', flat=True).distinct()
    
    for topic_name in unique_topics:
        topic_str = str(topic_name).strip()[:100]  # Limit to 100 chars
        if topic_str:
            Topic.objects.get_or_create(name=topic_str)
    
    print(f"✓ Created {len(unique_topics)} topics")


