def map_topics_to_fk(apps, schema_editor):
    """Map topic names to Topic FK IDs using raw SQL"""
    with schema_editor.connection.cursor() as cursor:
        # For each topic name, find its ID and update questions
        cursor.execute("SELECT DISTINCT topic FROM quiz_question WHERE topic IS NOT NULL")
        topics = cursor.fetchall()
        
        for (topic_name,) in topics:
            topic_str = str(topic_name).strip()[:100]
            if topic_str:
                # Get Topic ID
                cursor.execute("SELECT id FROM quiz_topic WHERE name = %s", [topic_str])
                result = cursor.fetchone()
                if result:
                    topic_id = result[0]
                    cursor.execute(
                        "UPDATE quiz_question SET topic_id = %s WHERE topic = %s",
                        [topic_id, topic_name]
                    )
        
        print(f"✓ Mapped {len(topics)} topics to FK IDs")


